/// stdout contract: with `--json`, WidgetForge writes exactly ONE JSON document to
/// stdout and diagnostics/usage errors to stderr. Exit codes are 0 / 1 / 2.
///
/// Three groups, kept separate on purpose:
///
/// 1. WidgetForge CLI contract (`dart run`)           - always runs.
/// 2. WidgetForge CLI contract (compiled executable)  - always runs (no network).
/// 3. Dart SDK launcher characterization              - opt-in, see below.
///
/// Group 3 records how the launcher generated by `dart pub global activate
/// --source path .` behaves. On Dart SDK 3.8.0 that launcher falls back to
/// `dart pub global run`, which prints pub's "Resolving dependencies..." output to
/// stdout. That is a pub/SDK behavior, not a WidgetForge defect, so group 3 does
/// not fail merely because it is observed. It classifies the outcome:
///
///   NOT REPRODUCED  stdout is a single JSON document (SDK defect absent/fixed here)
///   REPRODUCED      stdout = pub noise followed by byte-for-byte the JSON that
///                   `dart run` prints; exit codes preserved
///   (anything else) FAILS: exit codes changed, JSON damaged or noise after JSON
///                   -> that would be a real problem to investigate
///
/// Run group 3 with (needs a populated pub cache; it never touches the network
/// unless the cache is missing packages, and never modifies this checkout):
///
///   WIDGETFORGE_TEST_GLOBAL_LAUNCHER=1 dart test test/cli_stdout_contract_test.dart
///
/// Add WIDGETFORGE_EXPECT_CLEAN_LAUNCHER=1 to ALSO fail when the SDK defect is
/// reproduced (e.g. to assert that a newer SDK fixed it).
@Timeout(Duration(minutes: 5))
library;

import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

ProcessResult dartRun(List<String> args) =>
    Process.runSync('dart', ['run', 'bin/widgetforge.dart', ...args]);

/// Asserts stdout is exactly one JSON object. The failure message shows the
/// first stdout lines so a polluted stream is obvious.
Map<String, dynamic> expectSingleJsonDocument(String out, String what) {
  final head = out.split('\n').take(3).join(' | ');
  Object? decoded;
  try {
    decoded = jsonDecode(out);
  } on FormatException {
    fail('$what: stdout is not a single JSON document. First lines: "$head"');
  }
  expect(decoded, isA<Map<String, dynamic>>(), reason: what);
  return decoded as Map<String, dynamic>;
}

/// Contract checks shared by every way of launching WidgetForge.
void contractCases(ProcessResult Function(List<String> args) run, {required String label}) {
  const cases = {
    'ok_basic': 0,
    'err_entrypoint_missing': 1,
    'err_unsupported_view': 1,
  };
  for (final e in cases.entries) {
    test('$label ${e.key}: stdout is one JSON document, stderr empty, exit ${e.value}', () {
      final r = run(['doctor', '--json', p.absolute('fixtures', e.key)]);
      expect(r.exitCode, e.value);
      final j = expectSingleJsonDocument(r.stdout as String, '$label ${e.key}');
      expect(j['schemaVersion'], '1');
      expect(r.stderr, isEmpty);
    });
  }

  test('$label: exit 2 (not a Flutter project): stdout empty, message on stderr', () {
    final r = run(['doctor', '--json', p.absolute('docs')]);
    expect(r.exitCode, 2);
    expect(r.stdout, isEmpty);
    expect(r.stderr, isNotEmpty);
  });

  test('$label: exit 2 (unknown option): stdout empty', () {
    final r = run(['doctor', '--json', '--bogus']);
    expect(r.exitCode, 2);
    expect(r.stdout, isEmpty);
  });

  test('$label: repeated runs give byte-identical stdout', () {
    final args = ['doctor', '--json', p.absolute('fixtures', 'err_unsupported_view')];
    expect(run(args).stdout, run(args).stdout);
  });
}

void main() {
  group('1. WidgetForge CLI contract (dart run)', () {
    contractCases(dartRun, label: 'dart run');
  });

  group('2. WidgetForge CLI contract (compiled executable)', () {
    late Directory tmp;
    late String exe;
    String? setupProblem;

    setUpAll(() {
      tmp = Directory.systemTemp.createTempSync('wf_exe_');
      exe = p.join(tmp.path, Platform.isWindows ? 'widgetforge.exe' : 'widgetforge');
      final r = Process.runSync('dart', ['compile', 'exe', 'bin/widgetforge.dart', '-o', exe]);
      if (r.exitCode != 0) setupProblem = 'dart compile exe failed: ${r.stderr}';
    });
    tearDownAll(() {
      if (tmp.existsSync()) tmp.deleteSync(recursive: true);
    });

    ProcessResult runExe(List<String> args) => Process.runSync(exe, args);

    contractCases((args) {
      if (setupProblem != null) fail(setupProblem!);
      return runExe(args);
    }, label: 'exe');

    test('exe stdout equals `dart run` stdout', () {
      if (setupProblem != null) fail(setupProblem!);
      final args = ['doctor', '--json', p.absolute('fixtures', 'err_unsupported_view')];
      expect(runExe(args).stdout, dartRun(args).stdout);
    });
  });

  final optIn = Platform.environment['WIDGETFORGE_TEST_GLOBAL_LAUNCHER'] == '1';
  final expectClean = Platform.environment['WIDGETFORGE_EXPECT_CLEAN_LAUNCHER'] == '1';

  group(
      '3. Dart SDK launcher characterization '
      '(path activation; observed outcome is not a WidgetForge defect)',
      skip: optIn
          ? false
          : 'Opt-in: set WIDGETFORGE_TEST_GLOBAL_LAUNCHER=1 (needs a populated pub cache).', () {
    late Directory work;
    late Map<String, String> env;
    late String launcher;
    String? setupProblem;
    final observed = <String, String>{}; // scenario -> 'clean' | 'polluted'

    ProcessResult launch(List<String> args) => Process.runSync(launcher, args,
        environment: env, workingDirectory: Directory.systemTemp.path);

    setUpAll(() {
      work = Directory.systemTemp.createTempSync('wf_global_');
      // Work on a COPY: pub rewrites .dart_tool/ and pubspec.lock of a path package.
      final src = Directory(p.join(work.path, 'src'))..createSync();
      for (final name in ['bin', 'lib']) {
        _copy(Directory(name), Directory(p.join(src.path, name)));
      }
      for (final name in ['pubspec.yaml', 'analysis_options.yaml']) {
        File(name).copySync(p.join(src.path, name));
      }
      // Isolated pub cache that reuses already-downloaded packages.
      final realCache = Platform.environment['PUB_CACHE'] ??
          p.join(Platform.environment['HOME'] ?? '', '.pub-cache');
      final cache = Directory(p.join(work.path, 'cache'))..createSync();
      for (final sub in ['hosted', 'hosted-hashes']) {
        final real = Directory(p.join(realCache, sub));
        if (real.existsSync()) Link(p.join(cache.path, sub)).createSync(real.path);
      }
      env = {'PUB_CACHE': cache.path};
      final act = Process.runSync(
          'dart', ['pub', 'global', 'activate', '--source', 'path', '.'],
          workingDirectory: src.path, environment: env);
      if (act.exitCode != 0) {
        setupProblem = 'could not install the path launcher (${act.stderr}); result inconclusive';
      }
      launcher = p.join(cache.path, 'bin', 'widgetforge');
    });

    tearDownAll(() {
      if (work.existsSync()) work.deleteSync(recursive: true);
    });

    /// Runs one scenario and classifies stdout. Fails ONLY for outcomes that are
    /// not explained by launcher noise in front of WidgetForge's own output.
    void scenario(String name, String fixture, int expectedExit) {
      test('$name (exit $expectedExit)', () {
        if (setupProblem != null) {
          markTestSkipped(setupProblem!);
          return;
        }
        final target = fixture == '_tmp' ? Directory.systemTemp.path : p.absolute('fixtures', fixture);
        final r = launch(['doctor', '--json', target]);
        final out = r.stdout as String;

        expect(r.exitCode, expectedExit,
            reason: 'the launcher must preserve the exit-code contract');

        if (expectedExit == 2) {
          if (out.isEmpty) {
            observed[name] = 'clean';
          } else {
            expect(out.contains('{'), isFalse,
                reason: 'exit 2 must not print a JSON document; stdout was: $out');
            observed[name] = 'polluted';
          }
        } else {
          // Reference output: exactly what WidgetForge itself prints.
          final reference = dartRun(['doctor', '--json', target]).stdout as String;
          if (out == reference) {
            observed[name] = 'clean';
          } else {
            expect(out.endsWith(reference), isTrue,
                reason: 'stdout must be launcher noise FOLLOWED BY WidgetForge\'s '
                    'unchanged JSON. First lines: "${out.split('\n').take(3).join(' | ')}"');
            final noise = out.substring(0, out.length - reference.length);
            expect(noise.contains('{'), isFalse, reason: 'noise must not contain JSON');
            observed[name] = 'polluted';
          }
        }
        // Not a failure: a recorded observation, with the interpretation attached.
        // ignore: avoid_print
        print('[sdk-launcher] $name -> ${observed[name]} (Dart ${Platform.version.split(' ').first})');
      });
    }

    scenario('first run after install', 'ok_basic', 0);
    scenario('re-run', 'ok_basic', 0);
    scenario('findings', 'err_entrypoint_missing', 1);
    scenario('not a project', '_tmp', 2);

    test('summary: is the SDK launcher defect reproduced here?', () {
      if (setupProblem != null) {
        markTestSkipped(setupProblem!);
        return;
      }
      if (observed.length < 4) {
        // A scenario failed (or did not run): the launcher result is not interpretable.
        // ignore: avoid_print
        print('[sdk-launcher] INCONCLUSIVE: only ${observed.length}/4 scenarios were '
            'classified; see the failing scenario tests above.');
        return;
      }
      final reproduced = observed.values.contains('polluted');
      // ignore: avoid_print
      print(reproduced
          ? '[sdk-launcher] REPRODUCED on Dart ${Platform.version.split(' ').first}: '
              'the path launcher prints pub output to stdout. WidgetForge output and '
              'exit codes are unchanged. Use `dart run` or a compiled executable for JSON.'
          : '[sdk-launcher] NOT REPRODUCED on Dart ${Platform.version.split(' ').first}: '
              'the path launcher produced clean JSON in every scenario. '
              'Re-evaluate the README install guidance for this SDK version.');
      if (expectClean) {
        expect(reproduced, isFalse,
            reason: 'WIDGETFORGE_EXPECT_CLEAN_LAUNCHER=1 requires a clean launcher');
      }
    });
  });
}

void _copy(Directory from, Directory to) {
  to.createSync(recursive: true);
  for (final e in from.listSync(recursive: false)) {
    final target = p.join(to.path, p.basename(e.path));
    if (e is Directory) {
      if (p.basename(e.path) == '.dart_tool') continue;
      _copy(e, Directory(target));
    } else if (e is File) {
      e.copySync(target);
    }
  }
}
